passn("balance_compute", "code", code(r"""
p = 'load_balance'
nm = vars.get('cur_name') or str(g(p, 'productName'))
l4 = vars.get('cur_l4_words')
intro = ('Sonu ' + l4 + ' ile biten ' + nm + ' kartınıza ait') if nm else ('Sonu ' + l4 + ' ile biten kartınıza ait')
introk = ('Sonu ' + l4 + ' ile biten ' + nm + ' kartınızın') if nm else ('Sonu ' + l4 + ' ile biten kartınızın')
stmt = str(g(p, 'statementDate'))
lpd = str(g(p, 'lastPayDate'))
nsd = str(g(p, 'nextStatementDate'))
now = today()
CUR = [('TL', 'Türk Lirası'), ('USD', 'Dolar'), ('EUR', 'Euro'), ('GBP', 'İngiliz Sterlini')]
def blk(c):
    present = any(str(k).startswith(p + '_response.data.') and ('.debt' + c + '.') in str(k) for k in vars.keys())
    return present
def f(c, field):
    return num(g(p, 'debt' + c + '.' + field))
parts = []
if not stmt or not lpd:
    s = 'Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
    if nsd:
        s += ' İlk hesap kesim tarihiniz ' + sd(nsd) + ' olacak.'
    parts.append(s)
elif pd(nsd) and pd(nsd) == now:
    parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
    for c, w in CUR:
        if blk(c) and (f(c, 'totalDebt') or 0) > 0:
            parts.append(w + ' toplam borcunuz ' + amt(f(c, 'totalDebt')) + ' ' + w + "'dır.")
elif str(g(p, 'debtTL.statementPaymentStatus')) == 'NO_DEBT' and not any(blk(c) and (f(c, 'remainingDebt') or 0) > 0 for c, w in CUR[1:]):
    parts.append(introk + ' ' + sd(stmt) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + amt(g(p, 'debtTL.totalDebt', '0')) + " Türk Lirası'dır. Son ödeme tarihiniz " + sd(lpd) + ' olacaktır.')
    vars['nodebt'] = 'yes'
elif pd(lpd) and now > pd(lpd):
    parts.append(intro + ' ' + sd(stmt) + ' tarihinde kesilen ekstrenin son ödeme tarihi ' + sd(lpd) + ' idi ve bu tarih geçti.')
    for c, w in CUR:
        if blk(c) and (f(c, 'totalDebt') or 0) > 0:
            parts.append(w + ' toplam borcunuz ' + amt(f(c, 'totalDebt')) + ' ' + w + "'dır.")
    ra = f('TL', 'remainAutomaticPaymentAmount') or 0
    if str(g(p, 'automaticPaymentFlag')).upper() == 'Y' and ra > 0:
        parts.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + amt(ra) + " Türk Lirası'dır.")
else:
    opened = False
    clear = []
    def op():
        return intro + ' ' + sd(stmt) + ' tarihinde kesilen ekstre '
    if blk('TL') and (f('TL', 'remainingDebt') or 0) > 0:
        X = amt(f('TL', 'statementDebt')); Z = amt(f('TL', 'minPayment')); Y = amt(f('TL', 'remainingDebt')); TT = f('TL', 'remainingMinPayment') or 0
        mp = f('TL', 'minPayment') or 0
        if TT > 0 and TT >= mp:
            s = 'Türk Lirası borcunuz ' + X + ' Türk Lirası, ödenmesi gereken minimum tutar ' + Z + " Türk Lirası'dır."
        elif TT <= 0:
            s = 'Türk Lirası borcunuz ' + X + ' Türk Lirası, kalan toplam borcunuz ' + Y + " Türk Lirası'dır. Minimum ödemenizi yaptığınız için teşekkür ederiz."
        else:
            s = 'Türk Lirası borcunuz ' + X + ' Türk Lirası, ödenmesi gereken minimum tutar ' + Z + ' Türk Lirası, kalan toplam borcunuz ' + Y + ' Türk Lirası, kalan minimum ödeme tutarınız ' + amt(TT) + " Türk Lirası'dır."
        parts.append(op() + s); opened = True
    elif blk('TL'):
        clear.append('Türk Lirası')
    for c, w in CUR[1:]:
        if not blk(c):
            continue
        if (f(c, 'statementDebt') or 0) > 0 and (f(c, 'remainingDebt') or 0) > 0:
            s = w + ' borcunuz ' + amt(f(c, 'statementDebt')) + ' ' + w + ', kalan toplam borcunuz ' + amt(f(c, 'remainingDebt')) + ' ' + w + ', ödenmesi gereken minimum tutar ' + amt(f(c, 'minPayment')) + ' ' + w + "'dır."
            parts.append((op() if not opened else '') + s); opened = True
        else:
            clear.append(w)
    if clear and len(clear) < 4:
        parts.append((clear[0] if len(clear) == 1 else ', '.join(clear[:-1]) + ' ve ' + clear[-1]) + ' borcunuz bulunmamaktadır.')
    ra = f('TL', 'remainAutomaticPaymentAmount') or 0
    if pd(lpd) and now > pd(lpd) and str(g(p, 'automaticPaymentFlag')).upper() == 'Y' and ra > 0:
        parts.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + amt(ra) + " Türk Lirası'dır.")
    if pd(lpd) == now:
        parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
    else:
        d = sd(lpd)
        last = d.strip()[-1] if d.strip() else 'a'
        vow = [ch for ch in d if ch in 'aeıioöuüAEIİOÖUÜ']
        v = vow[-1] if vow else 'i'
        suf = {'a': 'dır', 'ı': 'dır', 'e': 'dir', 'i': 'dir', 'o': 'dur', 'u': 'dur', 'ö': 'dür', 'ü': 'dür'}.get(v.lower(), 'dir')
        if d.strip()[-1:].isdigit():
            lastd = int(d.strip()[-1])
            suf = {0: 'dır', 1: 'dir', 2: 'dir', 3: 'tür', 4: 'tür', 5: 'tir', 6: 'dır', 7: 'dir', 8: 'dir', 9: 'dur'}[lastd]
            if d.strip()[-2:] in ('00',):
                suf = 'dür'
        parts.append('Borçlarınız için son ödeme tarihiniz ' + d + "'" + suf + '.')
read = [x for x in str(vars.get('cards_read') or '').split(',') if x]
vars['more_cards'] = 'yes' if int(vars.get('n_cards') or 1) > len(read) else 'no'
vars['cur_currency'] = 'TL'
vars['cur_stmt_date'] = stmt
vars['reading'] = ' '.join(parts) + (' Başka bir kartınızın borcunu öğrenmek ister misiniz?' if vars['more_cards'] == 'yes' else '')
"""), [T("read_debt_more", "more cards", eq("more_cards", "yes")), T("email_get", "always")])

