                 "code": {"type": "string", "default": "import json, re, datetime\n" + COMMON + "try:\n" + "\n".join("    " + l for l in src.strip('\n').split('\n')) + "\nexcept Exception as e:\n    vars['code_error'] = str(e)\n"},
