def code(src):
    return [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
             "parameters": {"type": "object", "properties": {
                 "code": {"type": "string", "default": "import json, re, datetime\n" + COMMON + "try:\n" + "\n".join("    " + l for l in src.strip('\n').split('\n')) + "\nexcept Exception as e:\n    vars['code_error'] = str(e)\n"},
                 "timeout_ms": {"type": "number", "default": 10000}}}}}]

def leafs(d):
    return {k: {"type": "string", "default": v, "description": k} for k, v in d.items()}

def api(name, path, data, retries=1):
    return [{"type": "function", "config": {"timeoutMs": 20000, "maxRetries": retries},
             "function": {"name": name, "handler": "__function__:api_call", "description": name,
                          "parameters": {"type": "object", "properties": {
                              "url": {"type": "string", "default": BASE + path},
                              "method": {"type": "string", "default": "POST"},
                              "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
                              "body": {"type": "object", "properties": {
                                  "data": {"type": "object", "properties": leafs(data)},
                                  "call": {"type": "object", "properties": leafs({"lang": "tr"})}}, "required": []}}}}}]

def eq(var, val):
    return {"variable": var, "operator": "equals", "operand": val}
def T(target, desc, *conds):
    if not conds:
        return {"target_node": target, "description": desc, "condition": {"operator": "always"}}
    return {"target_node": target, "description": desc, "condition": {"logic": "or", "conditions": list(conds)}}

