if rel == 'M':
    vars['joint_line'] = 'Bu değişiklik kartınıza bağlı ' + rnm + ' kartınızı da etkileyecek. '
elif rel == 'C':
    vars['joint_line'] = 'Bu değişiklik kartınızın bağlı olduğu ' + rnm + ' kartınızı da etkileyecek. '
vars['week_intro'] = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + s + ' Hesap kesim tarihinizi değiştirmek ister misiniz?'
