vars['week_opts'] = ','.join(opts)
vars['week_options'] = 'Hesap kesim tarihinizi ayın ' + opts[0] + '., ' + opts[1] + '. ya da ' + opts[2] + '. haftasına alabilirim. Hangisini tercih edersiniz?'
